import { defineStore } from 'pinia'
import { {settingName}SettingsApi } from '@/services/settings/{settingName}SettingsApi'

export const use{SettingName}Settings = defineStore('{settingName}Settings', {
  state: () => ({
    settings: {},
    loading: false,
    error: null
  }),

  getters: {
    // Add computed properties
  },

  actions: {
    async fetchSettings() {
      this.loading = true
      try {
        this.settings = await {settingName}SettingsApi.getSettings()
      } catch (error) {
        this.error = error.message
      } finally {
        this.loading = false
      }
    },

    async saveSettings(settings) {
      this.loading = true
      try {
        await {settingName}SettingsApi.updateSettings(settings)
        this.settings = settings
      } catch (error) {
        this.error = error.message
        throw error
      } finally {
        this.loading = false
      }
    }
  }
})
